public class JDecInc2 {
	public static void main(String[] args) {
		//Khatwa 1: Ta'reef al-mutaghayyirat
		int a = 8; 
		int b = 3;
		//Khatwa 2: Tanfeedh al-amaliyyat wa tabi'at al-mukhraj al-awwal
		System.out.println( a++ + --b ); 
		//Khatwa 3: Tanfeedh al-amaliyyat wa tabi'at al-mukhraj al-thani
		System.out.println( ++a + b++ ); 
	}
}
